---@param SelectHouseType number @ SelectHouseType = 1 个人房屋信息 、SelectHouseType = 2 部队房屋信息、 SelectHouseType = 3 共享房屋信息
function HouseInfoPanelVM:HouseRoleInfoUpdate(MsgBody, SelectHouseType, RoomIndex)       
    if not MsgBody then
        return
    end

    local HouseBasicInfo = MsgBody.Basic
    local HouseType = HouseBasicInfo.HouseType
    self.HouseID = HouseBasicInfo.HouseID
    self.OwnerID = HouseBasicInfo.OwnerID
    self.HouseType = HouseType
    self.HouseName = _G.HouseInfoMgr:GetHouseNameStr(HouseBasicInfo.Name, HouseBasicInfo.Addr, self.HouseType, RoomIndex) 
    self.HouseGreet = HouseBasicInfo.Greeting
    self.LikesCount = HouseBasicInfo.BeLikeNum
    self.Tag = HouseBasicInfo.Tags
    self.TagTable = MathUtil.DecodeUint(self.Tag, 23)
    self.VisitPrivilege = HouseBasicInfo.VisitSetting
    self.EtherGid = HouseBasicInfo.EtherGid
    self.WorldID = HouseBasicInfo.WorldID
    self.PicUrl = HouseBasicInfo.PicUrl
    self.Addr = HouseBasicInfo.Addr
    local EstateInfoCfg = require("TableCfg/EstateInfoCfg")
    local EstateName = ""
    if HouseBasicInfo.Addr and EstateInfoCfg ~= nil then
        local EstateInfo = EstateInfoCfg:FindCfgByKey(HouseBasicInfo.Addr.EstateID) or {}
        EstateName = EstateInfo.EstateNameA
    end

    local HouseInfo = HouseCfg:FindCfgByKey(HouseBasicInfo.HouseResID)
    local HouseSize = ""
    if HouseInfo then
        HouseSize = HouseLocalDef.HouseInfoSizeStr[HouseInfo.Size]
    end
    self.HouseLoc  =_G.HouseLandMgr:GetHouseAddrStr(HouseBasicInfo.Addr, HouseBasicInfo.HouseResID, self.HouseType, RoomIndex)
    self.Roommates = {}
    if HouseType == ProtoCS.HouseType.HouseType_HouseType_Personal then
        self.Roommates = MsgBody.Roommates
    end

    -- 共享房屋主角需要显示在室友第一位
    if SelectHouseType == 3 and self.Roommates and  #self.Roommates >= 2 then
        if self.Roommates[1].RoleID ~= MajorUtil.GetMajorRoleID() then
            local Temp = self.Roommates[1]
            for i = 2, #self.Roommates do
                if self.Roommates[i].RoleID == MajorUtil.GetMajorRoleID() then
                    self.Roommates[1] = self.Roommates[i]
                    self.Roommates[i] = Temp
                    break
                end
            end
        end
    end

    self:UpdateTeleportText()
end

function HouseInfoPanelVM:HouseGroupInfoUpdate(MsgBody)
    if not MsgBody then
        _G.HouseMineMainPanelVM.CommEmptyVisibility = true
        _G.HouseMineMainPanelVM.InfoPanelVisibility = false
        return
    end

    self.GroupID = MsgBody.GroupID
    local HouseBasicInfo = MsgBody.HouseDetail.Basic
    self.OwnerID = HouseBasicInfo.OwnerID
    self.HouseID = HouseBasicInfo.HouseID
    self.HouseType = HouseBasicInfo.HouseType
    self.HouseGreet = HouseBasicInfo.Greeting
    self.LikesCount = HouseBasicInfo.BeLikeNum
    self.Tag = HouseBasicInfo.Tags
    self.TagTable = MathUtil.DecodeUint(self.Tag)
    self.VisitPrivilege = HouseBasicInfo.VisitSetting
    self.EtherGid = HouseBasicInfo.EtherGid
    self.WorldID = HouseBasicInfo.WorldID
    self.PicUrl = HouseBasicInfo.PicUrl
    self.Addr = HouseBasicInfo.Addr
    self.HouseName = _G.HouseInfoMgr:GetHouseNameStr(HouseBasicInfo.Name, HouseBasicInfo.Addr) 
    self.HouseLoc = _G.HouseLandMgr:GetHouseAddrStr(HouseBasicInfo.Addr, HouseBasicInfo.HouseResID)
    self:UpdateTeleportText()
end

function HouseInfoPanelVM:UpdateTeleportText()
    if self.EtherGid and self.EtherGid ~= 0 then
        self.TeleportText = HouseLocalDef.HouseInfoStr.TeleportText
    else
        if _G.AutoPathMoveMgr:IsAutoPathMoveEnable() then
            self.TeleportText = HouseLocalDef.HouseInfoStr.WayFinding
        else
            self.TeleportText = HouseLocalDef.HouseInfoStr.TraceText
        end
    end
end

function HouseInfoPanelVM:UpdateTagList()
    local TagCfg = nil
    if self.TagTable then
        for i =1, #self.TagTable do
            TagCfg = HouseFlagCfg:FindCfgByKey(self.TagTable[i])
            local TagList = {
                IconPath = nil,
                TagText = nil,
            }
            TagList.IconPath = string.format(HouseLocalDef.LocationHouseTagIconPath, TagCfg.ID, TagCfg.ID)
            TagList.TagText = TagCfg.FlagName
            table.insert(self.ShowTagList, TagList)
        end
    end
end

return HouseInfoPanelVM